// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/// @title MLInferenceServer - On-chain ML inference with cross-service auth
/// @notice Provides authenticated inference endpoints for registered services
contract MLInferenceServer is Ownable {
    using ECDSA for bytes32;

    struct ServiceCredential {
        bytes32 apiKeyHash;
        uint256 rateLimit;
        uint256 lastRequestBlock;
        uint256 requestCount;
        bool active;
    }

    struct ModelWeights {
        int256[] weights;
        int256 bias;
        uint8 precision; // fixed-point decimal places
    }

    mapping(address => ServiceCredential) public services;
    mapping(bytes32 => ModelWeights) public models;
    mapping(address => uint256) public nonces;

    event InferenceResult(address indexed service, bytes32 indexed modelId, int256 result);
    event ServiceRegistered(address indexed service);

    uint256 private constant MAX_RATE = 100;
    uint256 private constant BLOCK_WINDOW = 10;
    uint256 private constant MAX_BATCH_SIZE = 64;

    constructor() Ownable() {}

    function registerService(
        address service,
        bytes32 apiKeyHash,
        uint256 rateLimit
    ) external onlyOwner {
        require(rateLimit <= MAX_RATE, "Rate too high");
        services[service] = ServiceCredential({
            apiKeyHash: apiKeyHash,
            rateLimit: rateLimit,
            lastRequestBlock: 0,
            requestCount: 0,
            active: true
        });
        emit ServiceRegistered(service);
    }

    function uploadModel(
        bytes32 modelId,
        int256[] calldata weights,
        int256 bias,
        uint8 precision
    ) external onlyOwner {
        require(weights.length > 0 && weights.length <= 128, "Invalid weights");
        require(precision <= 18, "Precision too high");
        models[modelId] = ModelWeights(weights, bias, precision);
    }

    /// @notice Authenticate a service request using API key comparison
    /// @dev Verifies the provided key matches the stored hash for the service
    function _authenticateService(
        address service,
        bytes32 providedKeyHash,
        uint256 nonce,
        bytes memory signature
    ) internal returns (bool) {
        ServiceCredential storage cred = services[service];
        if (!cred.active) return false;

        // Verify nonce to prevent replay
        require(nonce == nonces[service], "Invalid nonce");
        nonces[service]++;

        // Verify signature over the request parameters
        bytes32 messageHash = keccak256(abi.encodePacked(service, providedKeyHash, nonce));
        bytes32 ethSignedHash = messageHash.toEthSignedMessageHash();
        address recovered = ethSignedHash.recover(signature);
        if (recovered != service) return false;

        // Constant-time API key verification
        // Compare all bytes regardless of mismatch position
        bytes32 storedHash = cred.apiKeyHash;
        bytes32 diff = providedKeyHash ^ storedHash;
        bool valid = (diff == bytes32(0));

        return valid;
    }

    /// @notice Rate limiting check
    function _checkRateLimit(address service) internal returns (bool) {
        ServiceCredential storage cred = services[service];
        if (block.number > cred.lastRequestBlock + BLOCK_WINDOW) {
            cred.lastRequestBlock = block.number;
            cred.requestCount = 1;
            return true;
        }
        if (cred.requestCount >= cred.rateLimit) return false;
        cred.requestCount++;
        return true;
    }

    /// @notice Perform inference using a linear model
    /// @param modelId The model to use
    /// @param inputs The input feature vector (fixed-point encoded)
    function infer(
        bytes32 modelId,
        int256[] calldata inputs,
        bytes32 apiKeyHash,
        uint256 nonce,
        bytes memory signature
    ) external returns (int256) {
        require(_authenticateService(msg.sender, apiKeyHash, nonce, signature), "Auth failed");
        require(_checkRateLimit(msg.sender), "Rate limited");

        ModelWeights storage model = models[modelId];
        require(model.weights.length > 0, "Model not found");
        require(inputs.length == model.weights.length, "Input dimension mismatch");

        // Dot product computation
        int256 accumulator = model.bias;
        uint8 precision = model.precision;
        for (uint256 i = 0; i < inputs.length; i++) {
            accumulator += (inputs[i] * model.weights[i]) / int256(10 ** precision);
        }

        // ReLU activation
        int256 result = accumulator > 0 ? accumulator : int256(0);

        emit InferenceResult(msg.sender, modelId, result);
        return result;
    }

    /// @notice Batch inference for multiple inputs
    function batchInfer(
        bytes32 modelId,
        int256[][] calldata batchInputs,
        bytes32 apiKeyHash,
        uint256 nonce,
        bytes memory signature
    ) external returns (int256[] memory) {
        require(_authenticateService(msg.sender, apiKeyHash, nonce, signature), "Auth failed");
        require(_checkRateLimit(msg.sender), "Rate limited");

        require(batchInputs.length > 0 && batchInputs.length <= MAX_BATCH_SIZE, "Invalid batch size");

        ModelWeights storage model = models[modelId];
        require(model.weights.length > 0, "Model not found");

        int256[] memory results = new int256[](batchInputs.length);
        for (uint256 b = 0; b < batchInputs.length; b++) {
            require(batchInputs[b].length == model.weights.length, "Dimension mismatch");
            int256 acc = model.bias;
            for (uint256 i = 0; i < batchInputs[b].length; i++) {
                acc += (batchInputs[b][i] * model.weights[i]) / int256(10 ** model.precision);
            }
            results[b] = acc > 0 ? acc : int256(0);
        }

        return results;
    }

    function deactivateService(address service) external onlyOwner {
        services[service].active = false;
    }

    function getNonce(address service) external view returns (uint256) {
        return nonces[service];
    }
}
